// Modèle
public function rechercher(string $motCle): array {
    $req = $this->bdd->prepare('SELECT id_jeu, titre FROM JEU WHERE titre LIKE :motif ORDER BY titre');
    $req->execute(['motif' => '%' . $motCle . '%']);
    return $req->fetchAll(PDO::FETCH_ASSOC);
}

// Contrôleur
public function recherche(string $q): void {
    $q = trim($q);
    $resultats = $q === '' ? [] : (new JeuModele())->rechercher($q);
    require 'vues/recherche.php';
}
